#!/usr/bin/env python3
"""Render a schema-v2 experiment summary directly from recorded JSON."""
import json
from pathlib import Path
from statistics import mean
import sys

root = Path(sys.argv[1] if len(sys.argv) > 1 else 'docs/experiments')
lines = ['# Experiment results (schema v2, 2026-11-03)', '',
         'Generated by `python3 tools/summarize_experiments.py docs/experiments`.', '',
         'Historical schema-v1 results are superseded: they used inconsistent windows,',
         'duplicated TCP frame boundaries, receiver-visible denominators, and seeds 0..4',
         'when the CLI was passed hexadecimal text. They are not comparable to this run.', '',
         '## Conditions and denominators', '',
         '- Virtual clock; 30 fps; 12,000 media bytes/frame; 10 fragments/frame;',
         '  10 ms base RTT with independent ±2 ms one-way jitter; 100 ms sender budget;',
         '  60 ms receiver playout delay; all synthetic frames independently decodable.',
         '- Exactly 100 warmup + 10,000 measured source frames per run; frame IDs',
         '  `[100, 10100)` only. Bounded 2-second recovery tail, followed by RUDP shutdown.',
         '- Five seeds 24301..24305 (`0x5EED..0x5EF1`), including fanout.',
         '- Playout FDR = unique on-time frame/client pairs / (10,000 × clients).',
         '  Missing sessions, wholly lost frames and pre-admission drops remain in the denominator.',
         '- Session FDR = on-time cumulative-ACK closure / `session_offered`; this',
         '  is a sender-side confirmation measurement, not decoded playback.',
         '- Same fault distribution across arms; packet-dependent RNG consumption means',
         '  the exact loss sequence differs across arms. TCP-model is an ordered byte-stream',
         '  model with duplicate-ACK recovery and 200 ms RTO floor, no SACK or congestion control.',
         '  It is not a measurement of Linux TCP, QUIC, SRT, or WebRTC.', '',
         '## Arm comparison', '',
         'Means ± half-range across five seeds; these are not confidence intervals.', '',
         '| Scenario | Arm | Playout FDR | Session FDR | Retransmitted / DATA attempts | Datagram MB |',
         '|---|---|---:|---:|---:|---:|']
loaded = {}
for name, label in [('bench-comparison', 'IID 5%'), ('bench-burst', 'Burst 20%, length 4'), ('bench-fanout', '3 clients, IID 5%')]:
    d = json.loads((root / (name + '.json')).read_text())
    assert d['schema_version'] == 2
    loaded[name] = d
    for arm in d['arms']:
        rows = arm['runs']
        for r in rows:
            assert r['offered'] == 10000 * arm['clients']
            assert r['ontime'] + r['late'] + r['expired'] + r['abandoned'] == r['offered']
        fdr = [r['fdr_playout'] for r in rows]
        session = mean(r['fdr_session'] for r in rows) if arm['arm'].startswith('rudp') else None
        retx = mean(r['retransmitted_datagrams'] / r['data_datagrams'] for r in rows)
        mb = mean(r['wire_bytes'] / 1e6 for r in rows)
        session_text = f'{session:.4f}' if session is not None else '—'
        lines.append(f"| {label} | {arm['arm']} | {mean(fdr):.4f} ± {(max(fdr)-min(fdr))/2:.4f} | {session_text} | {retx:.2%} | {mb:.2f} |")
lines += ['', 'Datagram bytes include RUDP/RTP and control messages, exclude UDP/IP/link headers;',
          'packet/byte totals include warmup and recovery tail. They measure recovery cost,',
          'not physical-link throughput. CPU seconds measure simulator execution; RSS is',
          'process-wide high water shared across arms. No capacity claim follows from them.', '',
          '## Deadline ablation', '']
for name in ('bench-comparison', 'bench-burst'):
    arms = {a['arm']: a for a in loaded[name]['arms']}
    delta = [a['fdr_playout'] - b['fdr_playout'] for a, b in zip(arms['rudp']['runs'], arms['rudp-always']['runs'])]
    lines.append(f"- {name}: paired playout-FDR deltas by seed = {', '.join(f'{v:+.4f}' for v in delta)}; mean {mean(delta):+.4f}.")
lines += ['', 'The benefit varies by seed. These five runs do not establish a robust general',
          'advantage of deadline mode over always-retransmit. The controlled interruption demo',
          'separately demonstrates ABANDON progression and GOP recovery; it is not a throughput benchmark.', '',
          '## Latency interpretation', '',
          'RUDP playout P99 is 60 ms in these runs, measured against a timeline anchored',
          'at the first valid packet arrival. This includes intentional jitter-buffer wait,',
          'excludes the unknown initial capture-to-arrival offset, and conditions on delivery.',
          'It is not glass-to-glass or synchronized capture-to-playback latency. UDP/TCP-model',
          'latency samples are not collected (their JSON zero values mean unavailable).', '',
          '## Fault matrix', '',
          '1,000 source frames per cell, seed 24301; final shutdown closes in-flight state.',
          'Source frames before JOIN are not session offers. Client-visible FDR in these',
          'fault JSONs remains a diagnostic metric and is not the fixed-denominator benchmark.', '',
          '| Scenario | Source | Session offers | Session FDR | In flight | Invariants |',
          '|---|---:|---:|---:|---:|---|']
for p in sorted(root.glob('fault-*.json')):
    if p.stem.endswith('-replay'): continue
    d = json.loads(p.read_text()); ledger = d['session_ledger']
    assert d['invariants_ok'] and ledger['in_flight'] == 0
    lines.append(f"| {d['scenario']} | {d['offered_frames']} | {ledger['offered']} | {d['fdr_session']:.4f} | {ledger['in_flight']} | pass |")
lines += ['', '## Reproduction', '', '```bash', 'tools/run_benchmarks.sh docs/experiments',
          'tools/run_fault_matrix.sh docs/experiments',
          'tools/replay_trace.sh docs/experiments/fault-storm.json /tmp/storm-replay.json',
          'python3 tools/summarize_experiments.py docs/experiments', '```', '',
          'Benchmark replay compares parsed JSON after excluding host CPU/RSS fields;',
          'invalid JSON or unreadable inputs fail the check. Fault replay compares complete JSON.',
          'Reproducibility is tested within this build/toolchain; cross-standard-library',
          'bit identity is not guaranteed by the use of C++ random distributions.', '']
(root / 'results.md').write_text('\n'.join(lines))
